{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"children":["header","directions-list"]}}
{"op":"add","path":"/elements/header","value":{"type":"ResultHeader","props":{"eyebrow":"Design proposals","title":"Directions for your deck","subtitle":"Each one is a theme, with its title slide drawn in it."},"children":[]}}
{"op":"add","path":"/elements/directions-list","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"repeat":{"statePath":"/result/directions"},"children":["direction-block"]}}
{"op":"add","path":"/elements/direction-block","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"children":["direction-separator","direction-split"]}}
{"op":"add","path":"/elements/direction-separator","value":{"type":"Separator","props":{"orientation":"horizontal"},"children":[]}}
{"op":"add","path":"/elements/direction-split","value":{"type":"Split","props":{"ratio":"2:1","gap":"xl"},"children":["direction-slide","direction-rail"]}}
{"op":"add","path":"/elements/direction-slide","value":{"type":"Picture","props":{"path":"mockup","alt":{"$template":"Title slide drawn in the ${theme/name} theme"}},"children":[]}}
{"op":"add","path":"/elements/direction-rail","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["theme-name","theme-style","theme-swatches","theme-details","theme-avoids"]}}
{"op":"add","path":"/elements/theme-name","value":{"type":"Heading","props":{"text":{"$item":"theme/name"},"level":"h2"},"children":[]}}
{"op":"add","path":"/elements/theme-style","value":{"type":"Text","props":{"text":{"$item":"theme/style/overall"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/theme-swatches","value":{"type":"Swatches","props":{"colors":[{"$item":"theme/colors/primary"},{"$item":"theme/colors/secondary"},{"$item":"theme/colors/accent"},{"$item":"theme/colors/background"},{"$item":"theme/colors/text_primary"},{"$item":"theme/colors/text_secondary"}]},"children":[]}}
{"op":"add","path":"/elements/theme-details","value":{"type":"Stack","props":{"direction":"vertical","gap":"none"},"children":["detail-typeface","detail-headings","detail-body","detail-layout","detail-icons","detail-graphics"]}}
{"op":"add","path":"/elements/detail-typeface","value":{"type":"Detail","props":{"label":"Typeface","value":{"$item":"theme/typography/font_family"}},"children":[]}}
{"op":"add","path":"/elements/detail-headings","value":{"type":"Detail","props":{"label":"Headings","value":{"$item":"theme/typography/heading_style"}},"children":[]}}
{"op":"add","path":"/elements/detail-body","value":{"type":"Detail","props":{"label":"Body","value":{"$item":"theme/typography/body_style"}},"children":[]}}
{"op":"add","path":"/elements/detail-layout","value":{"type":"Detail","props":{"label":"Layout","value":{"$template":"${theme/layout/aspect_ratio} · ${theme/layout/margins} margins · ${theme/layout/alignment} aligned"}},"children":[]}}
{"op":"add","path":"/elements/detail-icons","value":{"type":"Detail","props":{"label":"Icons","value":{"$item":"theme/style/icon_style"}},"children":[]}}
{"op":"add","path":"/elements/detail-graphics","value":{"type":"Detail","props":{"label":"Graphics","value":{"$item":"theme/style/graphic_style"}},"children":[]}}
{"op":"add","path":"/elements/theme-avoids","value":{"type":"Collapsible","props":{"title":"What it avoids","defaultOpen":false},"children":["theme-exclusions"]}}
{"op":"add","path":"/elements/theme-exclusions","value":{"type":"Text","props":{"text":{"$item":"theme/exclusions"},"variant":"body"},"children":[]}}
